select categories.id, 'Nitrile Rubber Tube', 'nitrile-rubber-tube', 'Fire-retardant, closed-cell elastomeric nitrile tubing for pipe insulation and condensation control.', 'Nitrile rubber tube insulation is a flexible, pre-formed, closed-cell elastomeric foam for pipework. It is suited to installations that need moisture-conscious thermal insulation with fast fitting around HVAC, plumbing, refrigeration and process service lines.', 'Elastomeric foam', '["High water-vapour resistance for low-temperature systems","Lightweight, flexible and fibre-free tubing","Closed-cell structure with stable thermal conductivity","Resistant to fungi, ozone and mild chemical exposure"]'::jsonb, '{"category":"Cold insulation","categorySlug":"cold-insulation","family":"Elastomeric foam","imageUrl":"/assets/products/nitrile-sheet-and-tubes.png","idealFor":["HVAC, split and window A/C piping","Plumbing, drainage and solar piping","Cold storage, clean rooms and process pipework"],"availableForms":["Pre-formed tube lengths: 1830 mm","Thicknesses from 6 mm to 19 mm","Pipe internal diameters from 6 mm to 42 mm","Tube combinations in common copper, MS, PVC and PPR pipe sizes"],"selectionNotes":["Match the tube internal diameter and thickness to the pipe and service","Confirm the operating condition and specified fire-performance requirement","Use the approved technical submittal for the offered material"],"technicalData":[{"description":"Cellular structure","standard":"Visual","unit":"","value":"Very fine, closed cell"},{"description":"Density","standard":"ASTM D 1667","unit":"kg/m3","value":"60 - 80"},{"description":"Thermal conductivity at mean temperature 25 deg C","standard":"EN 12667:2001","unit":"W/m.K","value":"0.034"},{"description":"Temperature limits","standard":"","unit":"deg C","value":"-55 to +105"},{"description":"Thermal stability (9 days at 90 deg C)","standard":"ASTM C534 / C534M-11","unit":"%","value":"3.3"},{"description":"Fire resistance","standard":"UL 94","unit":"","value