select categories.id, 'Nitrile Rubber Sheet', 'nitrile-rubber-sheet', 'High-performance, flexible closed-cell nitrile sheet for ducts, equipment and condensation-control insulation.', 'Nitrile rubber sheet is a flexible, closed-cell elastomeric foam designed to control condensation and limit heat gain or loss. Its sheet format is suited to HVAC ductwork, equipment, tanks, fittings and other broad or irregular surfaces where pre-formed tubing is not the right geometry.', 'Elastomeric foam', '["Low thermal conductivity and closed-cell moisture resistance","Fibre-free, low-VOC material","Resists fungi and bacterial growth","Flexible sheets with optional protective laminations"]'::jsonb, '{"category":"Cold insulation","categorySlug":"cold-insulation","family":"Elastomeric foam","imageUrl":"/assets/products/nitrile-sheet-and-tubes.png","idealFor":["HVAC insulation, refrigeration and chilled-water systems","A/C ductwork, tanks and pipe fittings","Clean rooms, cold storage and underdeck insulation"],"availableForms":["Flexible sheet insulation","Reinforced aluminium foil, glass cloth and other laminated formats","Plain and faced material for indoor or protected external use"],"selectionNotes":["Confirm the sheet thickness, facing and joint detail","Review the service temperature and moisture-control requirement","Use the approved technical submittal for the final supplied material"],"technicalData":[{"description":"Density","standard":"ASTM D 1622","unit":"kg/m3","value":"50 +/- 5"},{"description":"Temperature range*","standard":"EN 14706 and EN 14304","unit":"deg C","value":"0 to 105; -1 to -50 subject to the stated application note"},{"description":"Thermal conductivity","standard":"EN 12667 / ISO 8497","unit":"","value":"","isSection":true},{"description":"K value at 0 deg C","standard":"EN 12667 / ISO 8497","unit":"W/m.K","value":"0.035"},{"description":"K value at +20 deg C","standard":"EN 12667 / ISO 8497","unit":"W/m.K","value":"0.036"},{"description":"K value at +4