insert into public.products (category_id, name, slug, short_description, description, material, key_benefits, specifications, status, published_at, quotation_enabled, featured, active)
select categories.id, 'XLPE Underdeck Insulation', 'xlpe-underdeck-insulation', 'Foil-faced, closed-cell XLPE underdeck insulation for PEB and metal-roof thermal and vapour-control layers.', 'XLPE underdeck insulation is a closed-cell, cross-linked polyethylene foam used beneath metal roofing in pre-engineered building assemblies. Double aluminium-foil facings can provide a reflective layer and vapour-control component when installed with the required laps, tape and roof-fixing details.', 'Cross-linked polyethylene', '["Reflective foil faces help manage radiant energy transfer","Closed-cell foam supports a compact vapour-control layer","Can act as a secondary water barrier when installed along the roof slope","Low-weight roll handling for simultaneous roofing installation"]'::jsonb, '{"category":"Roof & PEB insulation","categorySlug":"roof-peb-insulation","family":"Cross-linked polyethylene","imageUrl":"/assets/products/xlpe-underdeck.jpeg","idealFor":["PEB sheds and industrial metal roofs","Warehouses and manufacturing facilities","Roof assemblies requiring thermal, reflective and secondary water-barrier layers"],"availableForms":["Aluminium-foil-faced underdeck rolls","Foil facing on both sides","Roll format installed over purlins and beneath metal roofing","Compatible aluminium foil tape and fixing details for sealed laps"],"selectionNotes":["Confirm the PEB roof build-up, purlin spacing and required thickness","Install laps, edge details and tape as part of a continuous system","Verify the final product, density and facing against the approved submittal"],"technicalData":[{"description":"Operating temperature (under intermittent exposure)*","standard":"ASTM D 3575","unit":"deg C","value":"-40 to 85; 85 to 115 for shorter exposure time"},{"description":"Density","standard":"ASTM D 3575","unit":"kg/m3","value":"28 +/- 3"},{"description":"Thermal conductivity (K value)*","standard":"ASTM C 518","unit":"","value":"","isSection":true},{"description":"K value at 0 deg C","standard":"ASTM C 518","unit":"W/m.K","value":"0.0318 - 0.0332"},{"description":"K value at 23 deg C","standard":"ASTM C 518","unit":"W/m.K","value":"0.0328 - 0.0345"},{"description":"K value at 45 deg C","standard":"ASTM C 518","unit":"W/m.K","value":"0.0333 - 0.0360"},{"description":"Solar direct reflectance","standard":"ASTM 1980-11","unit":"","value":"96.3"},{"description":"Water absorption*","standard":"ASTM D 1056","unit":"%","value":"2%"},{"description":"Water-vapour resistance factor, foam side","standard":"EN 12086","unit":"","value":"2,800"},{"description":"Water-vapour resistance factor, foil side","standard":"EN 12086","unit":"","value":">11,000"},{"description":"Oxygen index","standard":"ASTM D 2863","unit":"Index","value":"28"},{"description":"Surface spread of flame (aluminium-foil-faced material)","standard":"BS 476 Part 7, Class 1","unit":"Compliance","value":"Complied"},{"description":"Fire propagation (aluminium-foil-faced material)","standard":"BS 476 Part 6 & 7, Class 0","unit":"Compliance","value":"Complied"},{"description":"Sound insulation characteristic with GI sheet","standard":"","unit":"STC","value":"19 - 30 (reference curve)"}],"technicalDataNote":"*Reference values are supplied for early-stage selection only. Final performance is specific to the offered product density, thickness, facing and roof assembly."}'::jsonb, 'published', now(), false, true, true
from public.categories as categories where categories.slug = 'roof-peb-insulation'
on conflict (slug) do update set
  category_id = excluded.category_id,
