insert into public.products (category_id, name, slug, short_description, description, material, key_benefits, specifications, status, published_at, quotation_enabled, featured, active)
select categories.id, 'Glass Wool Blanket', 'glass-wool-blanket', 'Flexible resin-bonded glass-wool blanket for thermal, acoustic and fire-conscious roof, wall, HVAC and industrial assemblies.', 'Glass wool blanket is a resilient, resin-bonded mineral-fibre roll format for broad thermal and acoustic coverage. The blanket can follow roofs, ceilings, walls and ductwork, while density, thickness, facing and the complete installed assembly are selected around the project’s thermal, fire, moisture and sound-control needs.', 'Glass mineral wool', '["Low reference thermal conductivity at 25 deg C mean temperature","Reference sound absorption up to NRC 0.95","Lightweight, flexible roll handling with plain or faced options","Reference non-combustible material performance"]'::jsonb, '{"category":"Hot insulation","categorySlug":"hot-insulation","family":"Glass mineral wool","imageUrl":"/assets/products/glass-wool-blanket.png","idealFor":["Metal roofs, RCC underdecks, masonry walls and drywall","HVAC duct thermal insulation and acoustic wraps","Low-temperature equipment, solar-water-heater and mobility applications"],"availableForms":["Density range: 10 - 48 kg/m3","Thickness range: 25 - 130 mm","Width: 1.1 - 1.2 m; length: 7.5 - 30 m","Plain or faced rolls with aluminium, metallised-polypropylene or tissue-facing options"],"selectionNotes":["Confirm density, thickness and facing against the thermal, acoustic and fire objectives","Coordinate joint treatment, vapour strategy and the installation method with the complete assembly","Use the final offered product’s approved technical submittal for project sign-off"],"technicalData":[{"description":"Material range and thermal performance","standard":"","unit":"","value":"","isSection":true},{"description":"Material composition","standard":"","unit":"","value":"Resin-bonded glass wool"},{"description":"Reference product range","standard":"","unit":"kg/m3 / mm","value":"Density 10 - 48; thickness 25 - 130"},{"description":"Reference dimensions","standard":"","unit":"m","value":"Width 1.1 - 1.2; length 7.5 - 30"},{"description":"Facing options","standard":"","unit":"","value":"Plain; aluminium, metallised-polypropylene or tissue facings"},{"description":"Reference standard","standard":"IS 8183","unit":"","value":"Applicable code reference"},{"description":"Thermal conductivity at 25 deg C mean temperature","standard":"IS 8183 / IS 3346","unit":"W/m.K","value":"0.030 - 0.041"},{"description":"Thermal resistance at specific thickness","standard":"","unit":"m2.K/W","value":"25 mm: 0.6 - 0.8; 50 mm: 1.2 - 1.6"},{"description":"Noise reduction coefficient","standard":"ASTM C 423 / ISO 354","unit":"NRC","value":"0.65 - 0.95"},{"description":"Fire, moisture and material properties","standard":"","unit":"","value":"","isSection":true},{"description":"Non-combustibility","standard":"BS 476 Part 4 / IS 8183 / EN 13501","unit":"","value":"Non-combustible / incombustible; A1 reference classification"},{"description":"Surface spread of flame","standard":"BS 476 Part 7","unit":"","value":"Nil; Class 1"},{"description":"Fire propagation","standard":"BS 476 Parts 6 and 7","unit":"","value":"Class 0; index I <12; sub-index i1 <6"},{"description":"Moisture content","standard":"IS 3144 / IS 8183","unit":"%","value":"<2"},{"description":"Shot content","standard":"IS 3144 / IS 8183","unit":"","value":"Nil"},{"description":"Sulphur and chloride","standard":"IS 3144 / IS 8183","unit":"","value":"Negligible"},{"description":"Mould growth","standard":"IS 3144 / IS 8183","unit":"","value":"None"},{"description":"Alkalinity","standard":"IS 8183","unit":"pH","value":"7 - 10"}],"technicalDataNote":"Values are reference data for early-stage selection. Final thermal, fire, acoustic and moisture performance varies by density, thickness, facing and installed assembly; confirm the approved technical submittal before ordering."}'::jsonb, 'published', now(), false, false, true
from public.categories as categories where categories.slug = 'hot-insulation'
