select categories.id, 'Glass Wool Duct Board', 'glass-wool-duct-board', 'Rigid resin-bonded glass-wool board for duct thermal control, acoustic treatment and fire-conscious HVAC assemblies.', 'Glass wool duct board provides a more rigid material form for ductwork-related systems. It is selected in accordance with duct design, facing, handling needs and the project’s thermal and acoustic requirements.', 'Glass mineral wool', '["Low reference thermal conductivity at 25 deg C mean temperature","Reference sound absorption up to NRC 0.95","Rigid board format for less compression and sagging in selected applications","Reference non-combustible material performance"]'::jsonb, '{"category":"HVAC insulation","categorySlug":"hvac-insulation","family":"Glass mineral wool","imageUrl":"/assets/products/glass-wool-duct-board.png","idealFor":["HVAC duct thermal and acoustic insulation, including AHU rooms","RCC underdecks, masonry walls, facades, spandrels and drywall","Cold storage, small-furnace and train-coach insulation assemblies"],"availableForms":["Density range: 32 - 120 kg/m3","Thickness range: 15 - 100 mm","Standard width: 0.6 m; length: 1.2 m","Plain boards or aluminium, metallised-polypropylene, tissue and glass-cloth facing options"],"selectionNotes":["Confirm board density, thickness and facing against the duct, acoustic and fire-performance requirements","Coordinate board joints, fixings, vapour barrier and exposed-edge protection with the full assembly","Verify the final offered product''s approved technical submittal before ordering"],"technicalData":[{"description":"Material range and thermal performance","standard":"","unit":"","value":"","isSection":true},{"description":"Material composition","standard":"","unit":"","value":"Resin-bonded glass wool"},{"description":"Reference product range","standard":"","unit":"kg/m3 / mm","value":"Density 32 - 120; thickness 15 - 100"},{"description":"Reference dimensions","standard":"","unit":"m","value":"Width 0.6; length 1.2"},{"description":"Facing options","standard":"","unit":"","value":"Plain; aluminium, metallised-polypropylene, tissue or glass-cloth facings"},{"description":"Reference standard","standard":"IS 8183","unit":"","value":"Applicable code reference"},{"description":"Thermal conductivity at 25 deg C mean temperature","standard":"IS 8183 / IS 3346","unit":"W/m.K","value":"0.030 - 0.034"},{"description":"Thermal resistance at specific thickness","standard":"","unit":"m2.K/W","value":"25 mm: 0.76 - 0.8; 50 mm: 1.52 - 1.6"},{"description":"Noise reduction coefficient","standard":"ASTM C 423 / ISO 354","unit":"NRC","value":"0.65 - 0.95"},{"description":"Fire, moisture and material properties","standard":"","unit":"","value":"","isSection":true},{"description":"Non-combustibility","standard":"BS 476 Part 4 / IS 8183 / EN 13501","unit":"","value":"Non-combustible / incombustible; A1 reference classification"},{"description":"Surface spread of flame","standard":"BS 476 Part 7","unit":"","value":"Nil; Class 1"},{"description":"Fire propagation","standard":"BS 476 Parts 6 and 7","unit":"","value":"Class 0; index I <12; sub-index i1 <6"},{"description":"Moisture content","standard":"IS 3144 / IS 8183","unit":"%","value":"<2"},{"description":"Shot content","standard":"IS 3144 / IS 8183","unit":"","value":"Nil"},{"description":"Sulphur and chloride","standard":"IS 3144 / IS 8183","unit":"","value":"Negligible"},{"description":"Mould growth","standard":"IS 3144 / IS 8183","unit":"","value":"None"},{"description":"Alkalinity","standard":"IS 8183","unit":"pH","value":"7 - 10"}],"technicalDataNote":"Values are reference data for early-stage selection. Final thermal, acoustic, fire and moisture performance varies by density, thickness, facing and installed assembly; confirm the approved technical submittal before ordering."}'::jsonb, 'published', now(), false, false, true
