insert into public.products (category_id, name, slug, short_description, description, material, key_benefits, specifications, status, published_at, quotation_enabled, featured, active)
select categories.id, 'Glass Wool Flexible Duct', 'glass-wool-flexible-duct', 'Insulated flexible HVAC duct with a glass-wool layer, wire-helix core and reinforced vapour-barrier outer jacket.', 'Glass wool flexible duct is a flexible air-distribution connection for HVAC installations, commonly used between metal ducts and air terminals. Its layered construction combines a wire-helix inner core, a glass-wool insulation layer and a reinforced outer jacket, so duct diameter, run length, insulation, joints and support method should be selected as one complete system.', 'Glass mineral wool', '["Flexible connection around constrained HVAC routes","Reference thermal conductivity and thermal-resistance values for the insulation layer","Reinforced foil outer jacket that acts as a vapour barrier","Tear- and handling-resistant outer construction"]'::jsonb, '{"category":"HVAC insulation","categorySlug":"hvac-insulation","family":"Glass mineral wool","imageUrl":"/assets/products/glass-wool-flexible-duct.png","idealFor":["Connecting grilles and diffusers to metal ducts","Flexible HVAC distribution runs","Insulated air-distribution connections where compact routing is required"],"availableForms":["Insulated flexible duct density: 16 - 32 kg/m3","Diameter range: 4 - 20 inch","Length range: 10 - 25 ft","25 mm insulation thickness on insulated duct configurations"],"selectionNotes":["Confirm duct diameter, run length, insulation and required airflow performance","Coordinate supports, bends, joints and terminal connections to avoid excessive compression or kinking","Verify the final offered duct configuration, fire requirements and approved technical submittal before ordering"],"technicalData":[{"description":"Duct construction and range","standard":"","unit":"","value":"","isSection":true},{"description":"Insulated duct density","standard":"","unit":"kg/m3","value":"16 - 32"},{"description":"Duct diameter","standard":"","unit":"inch","value":"4 - 20"},{"description":"Duct length","standard":"","unit":"ft","value":"10 - 25"},{"description":"Insulation thickness, insulated duct","standard":"","unit":"mm","value":"25"},{"description":"Inner core","standard":"","unit":"","value":"Double-laminated film on coated steel-wire helix"},{"description":"Outer jacket","standard":"","unit":"","value":"Aluminium or metallised foil with fibreglass-yarn reinforcement"},{"description":"Outer-jacket function","standard":"","unit":"","value":"Vapour barrier; tear- and handling-resistant"},{"description":"Thermal and material properties","standard":"","unit":"","value":"","isSection":true},{"description":"Glass-wool thermal conductivity at 25 deg C mean temperature","standard":"","unit":"W/m.K","value":"0.032 - 0.039"},{"description":"Thermal resistance of insulation","standard":"","unit":"m2.K/W","value":"0.64 - 0.78"},{"description":"Temperature range","standard":"","unit":"deg C","value":"0 - 90"},{"description":"Fire rating of glass-wool core","standard":"BS 476 Part 4 / IS 8183","unit":"","value":"Non-combustible"},{"description":"Moisture content","standard":"IS 3144 / IS 8183","unit":"%","value":"<2"},{"description":"Shot content","standard":"IS 3144 / IS 8183","unit":"","value":"Nil"},{"description":"Sulphur and chloride","standard":"IS 3144 / IS 8183","unit":"","value":"Nil"},{"description":"Mould growth","standard":"IS 3144 / IS 8183","unit":"","value":"None"},{"description":"Alkalinity","standard":"IS 8183","unit":"pH","value":"7 - 10"}],"technicalDataNote":"Values are reference data for early-stage selection. Final HVAC performance depends on duct diameter, route, support spacing, insulation configuration, joints and installed assembly; confirm the approved technical submittal before ordering."}'::jsonb, 'published', now(), false, false, true
