insert into public.products (category_id, name, slug, short_description, description, material, key_benefits, specifications, status, published_at, quotation_enabled, featured, active)
select categories.id, 'Glass Wool Acoustic Board', 'glass-wool-acoustic-board', 'Dense resin-bonded glass-wool board for acoustic, thermal and fire-conscious building and HVAC assemblies.', 'Glass wool acoustic board is a rigid resin-bonded mineral-fibre panel for assemblies that require sound absorption alongside thermal and fire performance. It can be specified for ceilings, walls, duct systems and equipment areas when its thickness, density, facing and mounting detail are matched to the desired acoustic outcome.', 'Glass mineral wool', '["Reference acoustic performance with defined board and air-gap conditions","Low reference thermal conductivity at 25 deg C mean temperature","Dual-face foil and glass-cloth facing configuration","Reference non-combustible material performance"]'::jsonb, '{"category":"Acoustic insulation","categorySlug":"acoustic-insulation","family":"Glass mineral wool","imageUrl":"/assets/products/glass-wool-acoustic-board.png","idealFor":["Underdecks, false ceilings and masonry-wall treatments","HVAC duct thermal and acoustic systems, including AHU rooms","Gensets, testing areas and mobility HVAC-duct applications"],"availableForms":["Density range: 70 - 80 kg/m3","Thicknesses: 25 - 50 mm","Widths: 0.6 and 1.2 m; lengths: 1.2 and 2.5 m","FSK facing on one side with black-glass-cloth facing on the other"],"selectionNotes":["Confirm the required NRC, installed air gap, thickness and exposed area for the acoustic objective","Coordinate the board facing, fixings and joints with the HVAC or building assembly","Use the final offered product''s approved technical submittal for project approval"],"technicalData":[{"description":"Material range and thermal performance","standard":"","unit":"","value":"","isSection":true},{"description":"Material composition","standard":"","unit":"","value":"Resin-bonded glass wool"},{"description":"Reference product range","standard":"","unit":"kg/m3 / mm","value":"Density 70 - 80; thickness 25 - 50"},{"description":"Reference dimensions","standard":"","unit":"m","value":"Width 0.6 or 1.2; length 1.2 or 2.5"},{"description":"Facing configuration","standard":"","unit":"","value":"Foil-scrim-kraft one side; black glass cloth opposite side"},{"description":"Reference standard","standard":"IS 8183","unit":"","value":"Applicable code reference"},{"description":"Thermal conductivity at 25 deg C mean temperature","standard":"IS 8183 / IS 3346","unit":"W/m.K","value":"0.0306"},{"description":"Thermal resistance","standard":"","unit":"m2.K/W","value":"0.8 - 1.6; calculated from thickness and thermal conductivity"},{"description":"Noise reduction coefficient","standard":"ASTM C 423 / ISO 354","unit":"NRC","value":"0.65 at 25 mm; 0.75 with 35 mm air gap"},{"description":"Fire, moisture and material properties","standard":"","unit":"","value":"","isSection":true},{"description":"Non-combustibility","standard":"BS 476 Part 4 / IS 8183 / EN 13501","unit":"","value":"Non-combustible / incombustible; A1 reference classification"},{"description":"Surface spread of flame","standard":"BS 476 Part 7","unit":"","value":"Nil; Class 1"},{"description":"Fire propagation","standard":"BS 476 Parts 6 and 7","unit":"","value":"Class 0; index I <12; sub-index i1 <6"},{"description":"Moisture content","standard":"IS 3144 / IS 8183","unit":"%","value":"<2"},{"description":"Shot content","standard":"IS 3144 / IS 8183","unit":"","value":"Nil"},{"description":"Sulphur and chloride","standard":"IS 3144 / IS 8183","unit":"","value":"Negligible"},{"description":"Mould growth","standard":"IS 3144 / IS 8183","unit":"","value":"None"},{"description":"Alkalinity","standard":"IS 8183","unit":"pH","value":"7 - 10"}],"technicalDataNote":"Values are reference data for early-stage selection. Final acoustic, thermal, fire and moisture performance varies by thickness, density, facing, air gap and installed assembly; confirm the approved technical submittal before ordering."}'::jsonb, 'published', now(), false, true, true
