select categories.id, 'Ceramic Fibre Blanket', 'ceramic-fibre-blanket', 'Flexible ceramic-fibre blankets in alumina-silica and alumina-silica-zirconia configurations for high-temperature insulation.', 'Ceramic Fibre Blanket is a flexible refractory-insulation material for demanding high-temperature equipment. The alumina-silica configuration is classified to 1,260 deg C, while the alumina-silica-zirconia configuration is classified to 1,430 deg C. Final selection must account for the continuous operating temperature, density, mechanical protection and the complete installation design.', 'High-temperature fibre', '["Low thermal conductivity and heat storage","Flexible, resilient blanket handling","Resists thermal shock and supports elevated-temperature service"]'::jsonb, '{"category":"High-temperature insulation","categorySlug":"high-temperature-insulation","family":"High-temperature fibre","imageUrl":"/assets/products/ceramic-fibre-blanket.png","idealFor":["HRSG ducts, industrial and commercial chimneys","Boiler, furnace, heater and kiln back-up linings","Pipe wraps, metal launders and welding stress-relief work"],"availableForms":["Reference densities: 64, 96, 128 and 160 kg/m3","Blankets in project-specified thicknesses","Alumina-silica or alumina-silica-zirconia configurations"],"selectionNotes":["Match the configuration to the required classification and continuous-use temperature","Confirm density, thickness and conductivity against the duty conditions","Review refractory-system safety, anchors, facings and mechanical protection"],"technicalData":[{"description":"Reference product configurations","standard":"","unit":"","value":"","isSection":true},{"description":"Material composition","standard":"","unit":"","value":"Alumina-silica / Alumina-silica-zirconia"},{"description":"Colour","standard":"","unit":"","value":"White / White"},{"description":"Classification temperature","standard":"","unit":"deg C (deg F)","value":"1,260 (2,300) / 1,430 (2,600)"},{"description":"Continuous-use temperature","standard":"","unit":"deg C (deg F)","value":"1,180 (2,150) / 1,315 (2,400)"},{"description":"Melting point","standard":"","unit":"deg C (deg F)","value":"1,760 (3,200) / 1,760 (3,200)"},{"description":"Reference bulk densities","standard":"","unit":"kg/m3 (pcf)","value":"64, 96, 128, 160 (4, 6, 8, 10)"},{"description":"Tensile strength by density","standard":"EN 1094-1","unit":"kPa (psi)","value":"64: 30 (4.35); 96: 70 (10.15); 128: 90 (13.05); 160: 110 (15.95)"},{"description":"Typical chemical composition","standard":"","unit":"%","value":"Alumina-silica: SiO2 52-58, Al2O3 42-48; alumina-silica-zirconia: SiO2 48-52, Al2O3 33-37, ZrO2 13-17"},{"description":"Thermal conductivity (reference values)","standard":"","unit":"","value":"","isSection":true},{"description":"Alumina-silica at 200 / 400 / 600 deg C","standard":"ASTM C201","unit":"W/m.K","value":"64 / 96 / 128 kg/m3: 0.06 / 0.06 / 0.05 | 0.11 / 0.09 / 0.08 | 0.19 / 0.16 / 0.13"},{"description":"Alumina-silica at 800 / 1,000 deg C","standard":"ASTM C201","unit":"W/m.K","value":"64 / 96 / 128 kg/m3: 0.31 / 0.25 / 0.19 | 0.45 / 0.36 / 0.27"},{"description":"Alumina-silica-zirconia at 200 / 400 / 600 deg C","standard":"ASTM C201","unit":"W/m.K","value":"96 / 128 kg/m3: 0.07 / 0.05 | 0.10 / 0.08 | 0.16 / 0.14"},{"description":"Alumina-silica-zirconia at 800 / 1,000 / 1,200 deg C","standard":"ASTM C201","unit":"W/m.K","value":"96 / 128 kg/m3: 0.24 / 0.19 | 0.36 / 0.27 | 0.51 / 0.36"}],"technicalDataNote":"Reference values apply to the stated ceramic-fibre configuration and density. Confirm final performance, thickness, installation method and project suitability against current verified documentation before ordering."}'::jsonb, 'published', now(), false, false, true
