select categories.id, 'Mass Loaded Vinyl Barrier', 'mass-loaded-vinyl-barrier', 'Flexible dense barrier layer for acoustic assemblies where sound isolation is a stated design objective.', 'Mass loaded vinyl is commonly considered as one layer in an acoustic build-up. Its role should be assessed with the surrounding panels, seals, gaps and structural connection details rather than as a stand-alone sound-control solution.', 'Acoustic barrier layer', '["Flexible barrier-layer format","Can be integrated into layered assemblies","Compact sheet or roll handling"]'::jsonb, '{"category":"Acoustic insulation","categorySlug":"acoustic-insulation","family":"Acoustic barrier layer","imageUrl":"/assets/products/mass-loaded-vinyl-barrier.png","idealFor":["Acoustic partitions","Equipment enclosures","Service and room isolation details"],"availableForms":["Rolls","Cut sheets","Laminated assemblies"],"selectionNotes":["Define isolation versus absorption requirement","Coordinate perimeter seals","Confirm facing and fire requirements"],"technicalData":[],"technicalDataNote":""}'::jsonb, 'published', now(), false, false, true
