insert into public.products (category_id, name, slug, short_description, description, material, key_benefits, specifications, status, published_at, quotation_enabled, featured, active)
select categories.id, 'Water Tank Cover', 'water-tank-cover', 'Custom-fitted removable insulation cover for water-storage tanks, offered with XLPE or foil-bubble insulation constructions.', 'RAC Water Tank Cover is a made-to-measure external insulation cover for water-storage tanks. It wraps the tank body with a selected reflective insulation construction to help limit solar heat gain and heat absorption at the tank surface. The cover is developed around the tank geometry, connections and access requirements, using removable panels or a strapped wrap system for practical installation and maintenance.', 'Custom tank insulation cover', '["Helps reduce radiant solar heat gain at the tank surface","Supports more stable stored-water temperature in exposed locations","Custom fit around tank shape, piping, access points and supports","Removable strap or panel system for installation and maintenance","Reflective outer facing selected for the exposure and required finish","Available in XLPE and foil-bubble insulation constructions"]'::jsonb, '{"category":"Water Tank Cover","categorySlug":"water-tank-cover","family":"Custom tank insulation cover","imageUrl":"/assets/products/water-tank-cover.png","idealFor":["Vertical and horizontal cylindrical water-storage tanks","Square, rectangular and modular-panel tanks","Conical-top and dome-top tanks","Residential, commercial and industrial rooftop water tanks"],"availableForms":["XLPE closed-cell insulation with aluminium-foil facing","XLPE closed-cell insulation with GC cloth protective facing","Foil-bubble insulation with aluminium-foil facing","Vertical cylindrical, horizontal cylindrical, square / rectangular, conical-top and modular / panel tank cover designs","Custom cut, strapped or panelled cover sets made to the measured tank"],"selectionNotes":["Measure the tank diameter or length, height, roof profile and all pipe, manhole and ladder clearances","Select XLPE or foil-bubble construction according to the required build-up, facing and project budget","Confirm the final insulation thickness, external-facing requirement and fastening arrangement before manufacture","For outdoor installations, verify the cover detailing, water-shedding direction and exposure suitability for the selected facing","Confirm the final design from the tank survey and approved RAC offer before ordering"],"technicalData":[{"description":"Product type","standard":"RAC measured cover design","unit":"","value":"External, removable insulation cover for water-storage tanks"},{"description":"Insulation-core options","standard":"Selected RAC construction","unit":"","value":"Closed-cell XLPE insulation or foil-bubble insulation"},{"description":"Facing options","standard":"Selected RAC construction","unit":"","value":"Aluminium foil; GC cloth protective facing for XLPE construction"},{"description":"Tank geometry","standard":"Site measurement","unit":"","value":"Vertical / horizontal cylindrical, square / rectangular, conical-top or modular-panel tank"},{"description":"Cover configuration","standard":"RAC measured cover design","unit":"","value":"Custom wrap, removable panels and/or strap-fastened cover set"},{"description":"Site details to confirm","standard":"Site measurement","unit":"","value":"Tank dimensions, roof profile, access openings, piping, support legs and clearance requirements"},{"description":"Exterior exposure","standard":"Project requirement","unit":"","value":"Confirm facing, water-shedding detail, fastening and service exposure for the final installation"}],"technicalDataNote":"This custom cover is manufactured to the surveyed tank and selected material construction. Final performance depends on the tank condition, cover fit, insulation thickness, facing, installation details and site exposure. Confirm the approved RAC drawing and offer before manufacture."}'::jsonb, 'published', now(), false, false, true
from public.categories as categories where categories.slug = 'water-tank-cover'
on conflict (slug) do update set
  category_id = excluded.category_id,
